11	type ctxKey string
12	
13	const tenantCtxKey ctxKey = "tenant_id"
14	
15	func withTenantAuth(next http.Handler) http.Handler {
16		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
17			tenantID := ""
18	
19			if auth := r.Header.Get("Authorization"); strings.HasPrefix(auth, "Bearer ") {
20				token := strings.TrimPrefix(auth, "Bearer ")
21				if tid := extractTenantFromJWT(token); tid != "" {
22					tenantID = tid
23				}
24			}
25	
26			if tenantID == "" {
27				if tid := r.Header.Get("X-Tenant-ID"); tid != "" {
28					tenantID = tid
29				}
30			}
31	
32			if tenantID == "" {
33				tenantID = "default"
34			}
35	
36			ctx := context.WithValue(r.Context(), tenantCtxKey, tenantID)
37			next.ServeHTTP(w, r.WithContext(ctx))
38		})
39	}
40	
41	func tenantFromCtx(r *http.Request) string {
42		if tid, ok := r.Context().Value(tenantCtxKey).(string); ok && tid != "" {
43			return tid
44		}
45		return "default"
46	}
47	
48	func extractTenantFromJWT(token string) string {
49		parts := strings.Split(token, ".")
50		if len(parts) != 3 {
51			return ""
52		}
53	
54		payload, err := base64.RawURLEncoding.DecodeString(parts[1])
55		if err != nil {
56			return ""
57		}
58	
59		var claims struct {
60			TenantID string `json:"tenant_id"`
61			OrgID    string `json:"org_id"`
62		}
63		if err := json.Unmarshal(payload, &claims); err != nil {
64			return ""
65		}
66	
67		if claims.TenantID != "" {
68			return claims.TenantID
69		}
70		return claims.OrgID
71	}
