3	import (
4		"net/http"
5		"sync"
6		"time"
7	)
8	
9	type bucket struct {
10		tokens    float64
11		lastFill  time.Time
12		ratePerSec float64
13		capacity  float64
14	}
15	
16	type rateLimiter struct {
17		mu      sync.Mutex
18		buckets map[string]*bucket
19		free    float64
20		pro     float64
21	}
22	
23	func newRateLimiter() *rateLimiter {
24		return &rateLimiter{
25			buckets: make(map[string]*bucket),
26			free:    100.0 / 60.0,
27			pro:     10000.0 / 60.0,
28		}
29	}
30	
31	func (rl *rateLimiter) allow(tenantID string) bool {
32		rl.mu.Lock()
33		defer rl.mu.Unlock()
34	
35		b, ok := rl.buckets[tenantID]
36		if !ok {
37			rate := rl.free
38			b = &bucket{
39				tokens:    rate * 60,
40				lastFill:  time.Now(),
41				ratePerSec: rate,
42				capacity:  rate * 60,
43			}
44			rl.buckets[tenantID] = b
45		}
46	
47		now := time.Now()
48		elapsed := now.Sub(b.lastFill).Seconds()
49		b.tokens += elapsed * b.ratePerSec
50		if b.tokens > b.capacity {
51			b.tokens = b.capacity
52		}
53		b.lastFill = now
54	
55		if b.tokens < 1 {
56			return false
57		}
58		b.tokens--
59		return true
60	}
61	
62	func withRateLimit(rl *rateLimiter) func(http.Handler) http.Handler {
63		return func(next http.Handler) http.Handler {
64			return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
65				tenantID := tenantFromCtx(r)
66	
67				if !rl.allow(tenantID) {
68					w.Header().Set("Retry-After", "60")
69					http.Error(w, "rate limit exceeded", http.StatusTooManyRequests)
70					return
71				}
72	
73				next.ServeHTTP(w, r)
74			})
75		}
76	}
